def compare_versions(a: str, b: str) -> int:
    def parse(v):
        v = v.strip()
        # Strip build metadata (ignored for precedence)
        if '+' in v:
            v = v.split('+', 1)[0]
        pre = None
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core = v
        parts = core.split('.')
        nums = tuple(int(p) for p in parts[:3])
        while len(nums) < 3:
            nums = nums + (0,)
        pre_ids = pre.split('.') if pre is not None else None
        return nums, pre_ids

    def cmp(x, y):
        return (x > y) - (x < y)

    def compare_ident(x, y):
        xd = x.isdigit()
        yd = y.isdigit()
        if xd and yd:
            return cmp(int(x), int(y))
        if xd:
            return -1
        if yd:
            return 1
        return cmp(x, y)

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    c = cmp(core_a, core_b)
    if c != 0:
        return c

    # No pre-release has higher precedence than any pre-release
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for x, y in zip(pre_a, pre_b):
        c = compare_ident(x, y)
        if c != 0:
            return c

    return cmp(len(pre_a), len(pre_b))
